-- StorageCheckRepository.getMonthlySummary
with
  "months" as (
    select
      generate_series(
        date_trunc('month', $1::timestamptz),
        date_trunc('month', now()),
        interval '1 month'
      ) as "month"
  )
select
  to_char("months"."month", 'YYYY-MM') as "month",
  (
    select
      count(*)
    from
      "storage_check_run" r
    where
      date_trunc('month', r."startedAt") = "months"."month"
  ) as "runs",
  (
    select
      count(*)
    from
      "storage_check_run" r
    where
      date_trunc('month', r."startedAt") = "months"."month"
      and r."status" in ('issues', 'failed')
  ) as "runsWithProblems",
  (
    select
      coalesce(sum((r."stats" ->> 'bytes')::bigint), 0)
    from
      "storage_check_run" r
    where
      date_trunc('month', r."startedAt") = "months"."month"
      and r."kind" = 'verify'
  ) as "bytesVerified",
  (
    select
      count(*)
    from
      "storage_issue" i
    where
      date_trunc('month', i."confirmedAt") = "months"."month"
  ) as "issuesReported",
  (
    select
      count(*)
    from
      "storage_issue" i
    where
      i."confirmedAt" is not null
      and date_trunc('month', i."resolvedAt") = "months"."month"
  ) as "issuesResolved"
from
  "months"
order by
  "months"."month"

